CREATE TEMP TABLE stage_events (
  qid text PRIMARY KEY, title text, summary text,
  start_year int, start_month smallint, start_day smallint,
  end_year int, end_month smallint, end_day smallint,
  precision date_precision, display_date text, importance smallint, url text,
  event_id bigint
) ON COMMIT DROP;
CREATE TEMP TABLE stage_links (qid text, term_slug text, relevance real, is_primary boolean) ON COMMIT DROP;
CREATE TEMP TABLE stage_tags (qid text, tag_slug text) ON COMMIT DROP;

INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q1970159', 'Battle of Grenada', 'The Battle of Grenada took place on 6 July 1779 during the American Revolutionary War in the West Indies between the British Royal Navy and the French Navy, just off the coast of Grenada. A British fleet led by Admiral John Byron (the grandfather of Lord Byron) had sailed in an attempt to relieve Grenada, which French forces under Charles Henri Hector, Count of Estaing had just captured.', 1779, 7, 6, NULL, NULL, NULL, 'day', '6 July 1779', 50, 'https://en.wikipedia.org/wiki/Battle_of_Grenada'),
  ('Q3403859', 'Capture of Grenada', 'The capture of Grenada was an amphibious expedition in July 1779 during the American Revolutionary War. A French fleet under Admiral Charles Henri Hector, Count of Estaing captured the island of Grenada from the British.', 1779, 7, 2, 1779, 7, 4, 'day', '2 July 1779 – 4 July 1779', 41, 'https://en.wikipedia.org/wiki/Capture_of_Grenada_(1779)'),
  ('Q501866', '1983 Invasion of Grenada', 'The United States and a coalition of Caribbean countries invaded the island nation of Grenada at dawn on 25 October 1983. It was codenamed Operation Urgent Fury by the U.S. military, and resulted in military occupation within a few days.', 1983, 10, 25, 1983, 12, 15, 'day', '25 October 1983 – 15 December 1983', 71, 'https://en.wikipedia.org/wiki/United_States_invasion_of_Grenada');

